source .venv/bin/activate && python3 -c "
import json
for f in ['docred_processed/train.jsonl', 'docred_processed/dev.jsonl']:
    errs = 0
    with open(f) as fh:
        for i, line in enumerate(fh):
            try:
                obj = json.loads(line)
                assert 'input' in obj and 'output' in obj and 'meta' in obj
                out = json.loads(obj['output'])
                assert 'relations' in out
                for r in out['relations']:
                    assert all(k in r for k in ['head','tail','relation','evidence'])
            except Exception as e:
                errs += 1
                if errs <= 2:
                    print(f'  Error in {f} line {i}: {e}')
    print(f'{f}: {i+1} lines, {errs} errors')
"
